REPORTED = "commonly_reported"
OFFICIAL = "official_guidance"
PRACTICE = "practice"


def Q(
    qid: str,
    kind: str,
    text: str,
    roles: list[str],
    levels: list[str],
    competencies: list[str],
    difficulty: int,
    rubric: list[str],
    followups: list[str],
    pitfalls: list[str] | None = None,
    provenance: str = REPORTED,
    companies: list[str] | None = None,
    note: str = "",
    urls: list[str] | None = None,
    priority: float = 0.6,
) -> dict:
    return {
        "id": qid,
        "kind": kind,
        "text": text,
        "role_families": roles,
        "levels": levels,
        "competencies": competencies,
        "difficulty": difficulty,
        "rubric": rubric,
        "followups": followups,
        "pitfalls": pitfalls or [],
        "provenance": provenance,
        "companies": companies or [],
        "source_note": note,
        "source_urls": urls or [],
        "priority": priority,
    }


STAR = "Specific situation and the stakes, your own actions (\"I\", not only \"we\"), and a concrete, ideally measurable result"

